krpano.action:
tween(scale, 1.06, 0.35, easeOutQuad);
if(hotspot[calc('glow_' + name)] !== null,
	tween(hotspot[calc('glow_' + name)].alpha, 0.85, 0.4);
);
tooltip_show(get(tooltip));

tween(scale, 1.0, 0.45, easeOutQuad);
if(hotspot[calc('glow_' + name)] !== null,
	tween(hotspot[calc('glow_' + name)].alpha, 0.0, 0.5);
);
tooltip_hide();

sound_ui_click();
lookto(%1, %2, %3, smooth(120, 20, 40), true, true,
	panel_open(%4);
	ambience_swell();
);

if(panel_current !== null,
	tween(layer[calc('panel_' + panel_current)].alpha, 0.0, 0.4, easeInQuad,
		set(layer[calc('panel_' + panel_current)].visible, false);
		set(panel_current, null);
	);
	lookto(get(view.hlookat), 4, 92, smooth(100, 20, 30));
);
